            i += 1
            continue
        # comment or minus
        if c == '-' and peek() == '-':
            # comment
            i += 2
            # long comment?
            if current() == '[':
                # check level
                j = i+1
                level = 0
                while j < n and src[j] == '=':
                    level += 1
                    j += 1
                if j < n and src[j] == '[':
                    # long comment
                    i = j+1
                    close = ']' + '='*level + ']'
