def lookup_var(name, frame):
    # name is str (identifier)
    # search locals then upvalues, else global via _ENV
    for scope in reversed(frame.scope_stack):
        if name in scope:
            box, attr = scope[name]
            return box[0]
    if name in frame.upvalues:
        uv = frame.upvalues[name]
        # uv could be Upvalue or tuple? Handle both.
