        elif isinstance(uv, tuple):
            # (box, attr)? box is list?
            box = uv[0]
            if isinstance(box, list):
                return box[0]
            else:
                return box
        elif isinstance(uv, list):
            return uv[0]
        else:
            return uv
    # global: via _ENV
